correct_example.code:
function _checkApproval(address withdrawer, ERC20 token, uint256 amount) internal {
    uint256 approval = withdrawApproval[withdrawer][token];
    if (approval < amount) revert NotApproved();
    if (approval != type(uint256).max) {
        // Atomic check-and-decrement via require on current state
        require(withdrawApproval[withdrawer][token] == approval, "approval changed");
        unchecked { withdrawApproval[withdrawer][token] = approval - amount; }
    }
}

function setApprovalFor(address withdrawer, ERC20 token, uint256 newApproval) external onlyAdmin {
    // Timelock or two-step approval change to prevent front-running
    pendingApproval[withdrawer][token] = newApproval;
    approvalChangeTimestamp[withdrawer][token] = block.timestamp + 2 days;
}

function applyPendingApproval(address withdrawer, ERC20 token) external {
    if (block.timestamp >= approvalChangeTimestamp[withdrawer][token]) {
        withdrawApproval[withdrawer][token] = pendingApproval[withdrawer][token];
    }
}

function withdraw(uint256 shares, address outputToken) external {
    uint256 amount = (totalAssets() * shares) / totalSupply();
    require(IERC20(outputToken).balanceOf(address(this)) >= amount, "insufficient vault balance");
    _burn(msg.sender, shares);
    uint256 toWithdraw = amount;
    if (IERC20(outputToken).balanceOf(address(this)) < amount) {
        toWithdraw = amount - IERC20(outputToken).balanceOf(address(this));
        IController(controller).withdraw(outputToken, toWithdraw);
        uint256 after = IERC20(outputToken).balanceOf(address(this));
        require(after >= amount, "controller withdrawal shortfall");
    }
    IERC20(outputToken).safeTransfer(msg.sender, amount);
}
